import os
from flask import Blueprint, send_file

bp = Blueprint('assets', __name__)
BASE = os.path.join(os.path.dirname(__file__), 'frontend', 'build')
PWA = ['registerSW.js', 'manifest.webmanifest', 'sw.js']


@bp.route('/', defaults={'path': ''})
@bp.route('/<path:path>')
def catch_all(path):
    if path in PWA or path.startswith('workbox-'):
        return send_file(os.path.join(BASE, path))
    return 'not found', 404
